#!/bin/sh
# One palette for the whole desktop. A palette is a file in ../themes; this
# script renders it into the five places the programs read their colours from,
# then tells the running ones to look again.
#
#   theme.sh list          id<TAB>name, one per palette
#   theme.sh current       id of the saved choice (nord if none or invalid)
#   theme.sh set <id>      save the choice, render, reload
#   theme.sh apply         render the saved choice, reload
#   theme.sh ensure        render only if a generated file is missing; reload
#                          nothing. Hyprland's autostart runs it before waybar,
#                          and Ansible may run it over SSH, so it must work
#                          with no graphical session at all.
#
# WHY GENERATED FILES AND NOT ONE CONFIG PER PROGRAM. Waybar, rofi, dunst,
# alacritty and Hyprland each have their own colour syntax and none can read
# the others. Each config keeps its layout and imports a small file of colours
# from here, so a tracked config never changes when the theme does. The
# generated files are gitignored: they are machine state, like state/screens.*.
#
# The choice is saved under XDG_STATE_HOME, not in the repo, for the same
# reason: it differs per machine and must not dirty the working tree.
set -eu

# Not resolved through symlinks on purpose: stow links this script into
# ~/.config/hypr/scripts, and ../themes is next to it there as well.
hypr_dir=$(cd "$(dirname "$0")/.." && pwd)
themes_dir="$hypr_dir/themes"

config_home="${XDG_CONFIG_HOME:-$HOME/.config}"
data_home="${XDG_DATA_HOME:-$HOME/.local/share}"
state_home="${XDG_STATE_HOME:-$HOME/.local/state}"

choice_file="$state_home/theme/current"
default_id=nord

out_waybar="$config_home/waybar/theme.css"
out_rofi="$data_home/rofi/themes/theme-colors.rasi"
out_dunst="$config_home/dunst/dunstrc.d/90-theme.conf"
out_alacritty="$config_home/alacritty/theme.toml"
out_hypr="$config_home/hypr/state/theme.lua"

colour_keys="BG BG_ALT LINE FG FG_SOFT FG_BRIGHT MUTED ACCENT CRIT_FG
RED ORANGE YELLOW GREEN CYAN BLUE PURPLE TEAL
ANSI0 ANSI1 ANSI2 ANSI3 ANSI4 ANSI5 ANSI6 ANSI7
ANSI8 ANSI9 ANSI10 ANSI11 ANSI12 ANSI13 ANSI14 ANSI15"

die() { printf 'theme.sh: %s\n' "$*" >&2; exit 1; }

valid_id() {
    case "$1" in
    '' | *[!a-z0-9-]*) return 1 ;;
    esac
    [ -f "$themes_dir/$1" ]
}

saved_id() {
    id=$(cat "$choice_file" 2>/dev/null || true)
    if valid_id "$id"; then
        printf '%s\n' "$id"
    else
        printf '%s\n' "$default_id"
    fi
}

# Source a palette into this shell, after checking it. The values land in CSS,
# rasi, TOML and Lua, so a typo must stop here and not become a parse error in
# five programs.
load_palette() {
    valid_id "$1" || die "unknown theme: $1"
    for k in NAME $colour_keys; do unset "$k"; done
    # shellcheck disable=SC1090
    . "$themes_dir/$1"
    [ -n "${NAME:-}" ] || die "$1: NAME is missing"
    for k in $colour_keys; do
        eval "v=\${$k:-}"
        case "$v" in
        '#'[0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f]) ;;
        *) die "$1: $k is missing or not #rrggbb" ;;
        esac
    done
}

# tmp + mv in the destination directory, so a program that re-reads on a file
# event never sees half a file.
write_atomic() {
    dest=$1
    mkdir -p "$(dirname "$dest")"
    tmp=$(mktemp "$(dirname "$dest")/.$(basename "$dest").XXXXXX")
    if cat >"$tmp" && chmod 644 "$tmp" && mv -f "$tmp" "$dest"; then
        return 0
    fi
    rm -f "$tmp"
    return 1
}

# Hyprland wants rgb(rrggbb): no hash.
bare() { printf '%s' "${1#\#}" | tr 'A-F' 'a-f'; }

render_waybar() {
    write_atomic "$out_waybar" <<EOT
/* generated by theme.sh — do not edit. Theme: $NAME */
@define-color bg $BG;
@define-color bg_alt $BG_ALT;
@define-color line $LINE;
@define-color fg $FG;
@define-color fg_soft $FG_SOFT;
@define-color fg_bright $FG_BRIGHT;
@define-color muted $MUTED;
@define-color accent $ACCENT;
@define-color red $RED;
@define-color orange $ORANGE;
@define-color yellow $YELLOW;
@define-color green $GREEN;
@define-color cyan $CYAN;
@define-color blue $BLUE;
@define-color purple $PURPLE;
@define-color teal $TEAL;
EOT
}

render_rofi() {
    write_atomic "$out_rofi" <<EOT
/* generated by theme.sh — do not edit. Theme: $NAME */
* {
    bg:     $BG;
    bg-alt: $BG_ALT;
    line:   $LINE;
    fg:     $FG;
    muted:  $MUTED;
    accent: $ACCENT;
}
EOT
}

# Drop-in: dunst reads dunstrc.d/*.conf after dunstrc, so only colours go here.
render_dunst() {
    write_atomic "$out_dunst" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
[global]
    frame_color = "$LINE"
    highlight = "$ACCENT"

[urgency_low]
    background = "$BG"
    foreground = "$FG"
    frame_color = "$LINE"

[urgency_normal]
    background = "$BG"
    foreground = "$FG_SOFT"
    frame_color = "$LINE"

[urgency_critical]
    background = "$RED"
    foreground = "$CRIT_FG"
    frame_color = "$ORANGE"
EOT
}

# Imported by alacritty.toml. Cursor and selection are left out on purpose:
# alacritty then draws them by inverting the cell, which suits every palette.
render_alacritty() {
    write_atomic "$out_alacritty" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
[colors.primary]
background = "$BG"
foreground = "$FG"

[colors.normal]
black = "$ANSI0"
red = "$ANSI1"
green = "$ANSI2"
yellow = "$ANSI3"
blue = "$ANSI4"
magenta = "$ANSI5"
cyan = "$ANSI6"
white = "$ANSI7"

[colors.bright]
black = "$ANSI8"
red = "$ANSI9"
green = "$ANSI10"
yellow = "$ANSI11"
blue = "$ANSI12"
magenta = "$ANSI13"
cyan = "$ANSI14"
white = "$ANSI15"
EOT
}

render_hypr() {
    write_atomic "$out_hypr" <<EOT
-- generated by theme.sh — do not edit. Theme: $NAME
hl.config({
    general = {
        col = {
            active_border   = "rgb($(bare "$ACCENT"))",
            inactive_border = "rgb($(bare "$LINE"))",
        },
    },
})
EOT
}

render() {
    load_palette "$1"
    render_waybar
    render_rofi
    render_dunst
    render_alacritty
    render_hypr
}

# Every reload is allowed to fail: the program may simply not be running.
# alacritty is not here — live_config_reload watches its imports itself — and
# neither is rofi, which reads the theme on every run.
reload() {
    pkill -USR2 -x waybar >/dev/null 2>&1 || true
    dunstctl reload >/dev/null 2>&1 || true
    if [ -n "${HYPRLAND_INSTANCE_SIGNATURE:-}" ]; then
        hyprctl reload >/dev/null 2>&1 || true
    fi
}

missing() {
    for f in "$out_waybar" "$out_rofi" "$out_dunst" "$out_alacritty" "$out_hypr"; do
        [ -f "$f" ] || return 0
    done
    return 1
}

case "${1:-}" in
list)
    for f in "$themes_dir"/*; do
        [ -f "$f" ] || continue
        ( load_palette "${f##*/}" && printf '%s\t%s\n' "${f##*/}" "$NAME" )
    done
    ;;
current)
    saved_id
    ;;
set)
    [ $# -eq 2 ] || die "usage: theme.sh set <id>"
    load_palette "$2"
    printf '%s\n' "$2" | write_atomic "$choice_file"
    render "$2"
    reload
    ;;
apply)
    render "$(saved_id)"
    reload
    ;;
ensure)
    # Says what it did, so a caller (Ansible) can tell rendering from a no-op.
    if missing; then
        render "$(saved_id)"
        printf 'rendered %s\n' "$(saved_id)"
    fi
    ;;
*)
    die "usage: theme.sh list | current | set <id> | apply | ensure"
    ;;
esac
